// ReportDetailModal — v7.3 restoration of the legacy IA Insights report
// modal. Replaces the inline accordion expand pattern that briefly shipped
// in v7.2 (which was the wrong move per design feedback).
//
// Layout:
//   - Header: title · period · close
//   - KPI tiles (from scoreInputs that carry numeric values)
//   - Hero callout (the first observation, rendered as a highlighted insight)
//   - Remaining observations
//   - Dark ARGUS Intelligence section with numbered findings
//   - Recommended actions
//   - Footer: "Generated by ARGUS · <period> · Next: <next>"
//
// Pure presentation — no data fetching. Caller passes everything it
// already has: meta, report (ReportAnalysis), history (for period
// labelling), and optional product accent color.

import { X } from "lucide-react";
import { MonthlyScoreBars } from "./MonthlyScoreBars";

// Local type — identical across ARION / SPARK / OLIVER trendEngines modules.
// We re-declare it here so the modal doesn't bind to any one product's
// engine module and can be reused across all three products.
export interface ReportAnalysis {
  score: number;
  scoreInputs: Array<{ key: string; value: number | string | null; weight: number; note?: string }>;
  observations: string[];
  actions: string[];
  contextNote?: string;
}

interface Meta {
  key: string;
  label: string;
  question: string;
  icon: any;
  weight: number;
}

interface Props {
  meta: Meta;
  report: ReportAnalysis;
  history: Array<{ period_end: string; score: number }>;
  /** Color used for KPI accents (defaults to ARION blue). */
  accent?: string;
  /** "ARION" | "SPARK" | "OLIVER" — colors the dark intelligence section badge. */
  product?: "ARION" | "SPARK" | "OLIVER";
  /** Period label (e.g. "Q1 2026 · Jan 1 – Mar 31, 2026"). */
  periodLabel?: string;
  /** Next-generated label (e.g. "July 1, 2026"). */
  nextLabel?: string;
  onClose: () => void;
}

function bandColor(score: number): string {
  if (score >= 70) return "#16A34A";
  if (score >= 50) return "#EAB308";
  if (score > 0)   return "#DC2626";
  return "#94A3B8";
}

function formatValue(v: unknown): string {
  if (v === null || v === undefined) return "—";
  if (typeof v === "number") {
    if (Math.abs(v) >= 1000) return v.toLocaleString(undefined, { maximumFractionDigits: 1 });
    if (!Number.isInteger(v)) return v.toFixed(2);
    return String(v);
  }
  return String(v);
}

export function ReportDetailModal({
  meta,
  report,
  history,
  accent = "#1A7DB5",
  product = "ARION",
  periodLabel,
  nextLabel,
  onClose,
}: Props) {
  const score = report.score;
  const scoreColor = bandColor(score);
  const Icon = meta.icon;

  // Promote up to 4 numeric scoreInputs into KPI tiles. Skip non-numeric.
  const kpis = report.scoreInputs
    .filter((s) => s.value !== null && s.value !== undefined && s.value !== "")
    .slice(0, 4);

  const observations = report.observations.filter(Boolean);
  const heroObservation = observations[0];
  const remainingObservations = observations.slice(1);

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4"
      onClick={onClose}
      role="dialog"
      aria-modal="true"
    >
      <div
        className="bg-white rounded-lg shadow-2xl max-w-3xl w-full max-h-[90vh] flex flex-col"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div className="flex items-start justify-between gap-3 border-b border-slate-200 px-5 py-4">
          <div className="flex items-start gap-3 min-w-0 flex-1">
            <div
              className="flex-shrink-0 h-10 w-10 rounded-full flex items-center justify-center"
              style={{ background: `${scoreColor}1A`, color: scoreColor }}
            >
              <Icon className="h-5 w-5" />
            </div>
            <div className="min-w-0">
              <h2 className="text-lg font-bold text-slate-900 truncate">{meta.label}</h2>
              <p className="text-xs text-slate-500">{periodLabel || meta.question}</p>
            </div>
          </div>
          <div className="flex items-center gap-3 flex-shrink-0">
            <div className="text-right">
              <div className="text-2xl font-bold tabular-nums" style={{ color: scoreColor }}>{score}</div>
              <div className="text-[9px] uppercase text-slate-400">/ 100</div>
            </div>
            <button
              onClick={onClose}
              className="p-1.5 hover:bg-slate-100 rounded text-slate-500"
              aria-label="Close"
            >
              <X className="h-5 w-5" />
            </button>
          </div>
        </div>

        {/* Scrollable body */}
        <div className="overflow-y-auto px-5 py-5 space-y-5 flex-1">
          {/* Hero callout — first observation as the headline insight */}
          {heroObservation && (
            <div className="rounded-md border-l-4 border-amber-400 bg-amber-50 px-4 py-3">
              <div className="text-xs font-semibold uppercase text-amber-800 tracking-wide mb-1">
                The insight
              </div>
              <p className="text-sm text-slate-800 leading-relaxed">{heroObservation}</p>
            </div>
          )}

          {/* KPI tiles */}
          {kpis.length > 0 && (
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
              {kpis.map((k) => (
                <div
                  key={k.key}
                  className="rounded-md border border-slate-200 bg-white px-3 py-2"
                  style={{ borderTopWidth: 3, borderTopColor: accent }}
                >
                  <div className="text-[10px] uppercase font-semibold text-slate-500 tracking-wide">
                    {k.key}
                  </div>
                  <div className="text-lg font-bold text-slate-900 tabular-nums mt-0.5">
                    {formatValue(k.value)}
                  </div>
                  <div className="text-[9px] text-slate-400 mt-0.5">
                    {Math.round(k.weight * 100)}% of score
                  </div>
                </div>
              ))}
            </div>
          )}

          {/* Score history bars */}
          {history.length >= 2 && (
            <div>
              <div className="flex items-center justify-between mb-1">
                <div className="text-[10px] uppercase font-semibold tracking-wide text-slate-500">
                  Score history
                </div>
                <div className="text-[9px] text-slate-400">
                  {history.length} period{history.length === 1 ? "" : "s"}
                </div>
              </div>
              <MonthlyScoreBars data={history} width={640} height={96} />
            </div>
          )}

          {/* ARGUS Intelligence section — dark themed */}
          <div className="rounded-lg bg-slate-900 text-slate-100 p-4">
            <div className="flex items-center gap-2 mb-3">
              <span
                className="text-[10px] font-bold uppercase tracking-wide px-2 py-0.5 rounded"
                style={{ background: "#84CC1620", color: "#A3E635" }}
              >
                ARGUS
              </span>
              <span className="text-sm font-semibold">
                Intelligence for {product.toLowerCase()} · {meta.label}
              </span>
            </div>

            {remainingObservations.length === 0 && !heroObservation ? (
              <p className="text-xs text-slate-400 italic">
                Not enough data yet — observations populate after the first scoring period.
              </p>
            ) : (
              <ol className="space-y-2.5">
                {remainingObservations.map((o, i) => (
                  <li key={i} className="flex items-start gap-3 text-xs leading-relaxed text-slate-200">
                    <span
                      className="flex-shrink-0 mt-0.5 h-5 w-5 rounded-full flex items-center justify-center text-[10px] font-bold"
                      style={{ background: "#EA580C", color: "white" }}
                    >
                      {i + 1}
                    </span>
                    <span>{o}</span>
                  </li>
                ))}
              </ol>
            )}

            {report.actions.length > 0 && (
              <>
                <div className="border-t border-slate-700 mt-4 pt-3">
                  <div className="text-[10px] font-bold uppercase tracking-wide mb-2" style={{ color: "#A3E635" }}>
                    Recommended actions
                  </div>
                  <ul className="space-y-2">
                    {report.actions.map((a, i) => (
                      <li key={i} className="flex items-start gap-2 text-xs leading-relaxed text-slate-200">
                        <span className="flex-shrink-0 mt-1 h-1.5 w-1.5 rounded-full" style={{ background: "#EA580C" }} />
                        <span>{a}</span>
                      </li>
                    ))}
                  </ul>
                </div>
              </>
            )}
          </div>

          {/* Score-input breakdown (kept for transparency, smaller) */}
          {report.scoreInputs.length > 0 && (
            <details className="text-xs">
              <summary className="cursor-pointer text-slate-500 hover:text-slate-700">
                Score breakdown
              </summary>
              <div className="grid grid-cols-2 gap-1.5 mt-2">
                {report.scoreInputs.map((s) => (
                  <div
                    key={s.key}
                    className="flex items-center justify-between bg-slate-50 rounded px-2 py-1"
                  >
                    <span className="text-[10px] text-slate-600 truncate">
                      {s.key} <span className="text-slate-400">({Math.round(s.weight * 100)}%)</span>
                    </span>
                    <span className="tabular-nums font-mono text-[10px] text-slate-900">
                      {formatValue(s.value)}
                    </span>
                  </div>
                ))}
              </div>
              {report.contextNote && (
                <div className="mt-2 text-[10px] italic text-amber-700">{report.contextNote}</div>
              )}
            </details>
          )}
        </div>

        {/* Footer */}
        <div className="flex items-center justify-between border-t border-slate-200 px-5 py-3 bg-slate-50 rounded-b-lg">
          <div className="text-[11px] text-slate-500">
            Generated by{" "}
            <span className="font-semibold" style={{ color: "#A3E635" }}>ARGUS</span>
            {periodLabel && <> · {periodLabel.split("·")[0].trim()}</>}
            {nextLabel && <> · Next: {nextLabel}</>}
          </div>
          <button
            onClick={onClose}
            className="px-4 py-1.5 text-xs bg-slate-900 text-white rounded hover:bg-slate-800"
          >
            Close
          </button>
        </div>
      </div>
    </div>
  );
}

export default ReportDetailModal;
